import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps
from hourglass.errors import OutsideHoursError, ProjectError


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def setUp(self):
        self.opening = parse_span("09:00-17:00")

    def test_gap_in_the_middle(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, self.opening),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = spans("10:00-16:00")
        self.assertEqual(
            find_gaps(worked, self.opening),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(
            find_gaps([], self.opening),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = spans("09:00-13:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, self.opening), [])

    def test_overlaps_and_order_do_not_matter(self):
        worked = spans("14:00-17:00", "09:00-13:00", "12:00-15:00")
        self.assertEqual(find_gaps(worked, self.opening), [])

    def test_starting_before_opening_raises(self):
        worked = spans("08:00-12:00")
        with self.assertRaises(OutsideHoursError):
            find_gaps(worked, self.opening)

    def test_ending_after_closing_raises(self):
        worked = spans("16:00-18:00")
        with self.assertRaises(OutsideHoursError):
            find_gaps(worked, self.opening)

    def test_error_is_a_project_error(self):
        with self.assertRaises(ProjectError):
            find_gaps(spans("00:00-01:00"), self.opening)
